### File 1: app/(app)/flash-events/actions.ts — append `markSlotWalkInAction`

Add a new server action that calls the RPC. Pattern matches the existing actions in the file.

```ts
import { z } from 'zod'

const walkInSchema = z.object({
  firstName: z.string().min(1).max(80),
  lastName: z.string().max(80).optional().nullable(),
  email: z.string().email(),
  phone: z.string().max(40).optional().nullable(),
  notes: z.string().max(500).optional().nullable(),
  designId: z.string().uuid().optional().nullable(),
  chargeAtDesk: z.boolean(),
})

export async function markSlotWalkInAction(
  eventId: string,
  slotId: string,
  formData: FormData
): Promise<ActionResult & { bookingId?: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  const raw = {
    firstName: formData.get('firstName'),
    lastName: formData.get('lastName') || null,
    email: formData.get('email'),
    phone: formData.get('phone') || null,
    notes: formData.get('notes') || null,
    designId: (() => {
      const v = formData.get('designId')
      return typeof v === 'string' && v !== '__none__' && v !== '' ? v : null
    })(),
    chargeAtDesk: formData.get('chargeAtDesk') !== 'false',
  }

  const parsed = walkInSchema.safeParse(raw)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
  }

  try {
    const { createServiceRoleClient } = await import('@/lib/supabase/server')
    const supabase = createServiceRoleClient()
    const { data, error } = await supabase.rpc('mark_flash_slot_walkin', {
      p_slot_id: slotId,
      p_client_info: {
        first_name: parsed.data.firstName,
        last_name: parsed.data.lastName,
        email: parsed.data.email,
        phone: parsed.data.phone,
        notes: parsed.data.notes,
        design_id: parsed.data.designId,
      },
      p_charge_at_desk: parsed.data.chargeAtDesk,
    })

    if (error) {
      logger.error({ error, eventId, slotId }, 'markSlotWalkInAction RPC failed')
      return { success: false, error: error.message }
    }

    const result = data as { booking_id?: string; error?: string } | null
    if (result?.error) {
      return { success: false, error: result.error }
    }

    // Audit log
    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.userId,
      'flash_event.slot.walk_in',
      { type: 'flash_event_slot', id: slotId },
      { eventId, bookingId: result?.booking_id, chargeAtDesk: parsed.data.chargeAtDesk },
      auth.studioId
    )

    revalidatePath(`/flash-events/${eventId}`)
    return { success: true, bookingId: result?.booking_id }
  } catch (err) {
    logger.error({ err, eventId, slotId }, 'markSlotWalkInAction failed')
    const message = err instanceof Error ? err.message : 'Failed to mark walk-in'
    return { success: false, error: message }
  }
}
```

NOTE: the audit `auth.userId` field may not exist — check the AuthenticatedUser type at lib/supabase/server.ts. If the field is `id` or `user.id`, adjust accordingly. Use the correct one.

If `mark_flash_slot_walkin` RPC isn't yet typed in lib/supabase/types.ts (Docker not running, types not regen), the `.rpc('mark_flash_slot_walkin', ...)` call will TS-error. Acceptable workaround: cast the supabase client to call rpc via a typed wrapper:
```ts
const { data, error } = await (supabase.rpc as unknown as (
  fn: 'mark_flash_slot_walkin',
  args: { p_slot_id: string; p_client_info: Record<string, unknown>; p_charge_at_desk: boolean }
) => Promise<{ data: { booking_id?: string; booking_token?: string; slot_id?: string; error?: string } | null; error: { message: string } | null }>)(
  'mark_flash_slot_walkin',
  { p_slot_id: slotId, p_client_info: {...}, p_charge_at_desk: parsed.data.chargeAtDesk }
)
```
NEVER use `any`. Use the typed wrapper above.

